-- Consulta: ArquivoMorto Arquivar
-- Tipo: Acréscimo (64)
-- Parâmetros: Formulários!ArquivoMorto!DataIniRel (Texto), Formulários!ArquivoMorto!DataFimRel (Texto)
-- Descrição: 

INSERT INTO ArquivoMorto ( EmpVinculada, CodigoParceiro, CodHistorico, DataMovto, ValorDebito, ValorCredito, Complemento, Plano1, Plano2, Plano3, ContaFinanceira, Confirmado, Integracao, DataPagto, DataVencto, MovPagtoLote, SelPagtoLote, Observacao, NumDoc, CodImovel, AgrupadorVenda, ClassificacaoVenda, SofreReajuste, IndiceReajuste, CodAtribuiParceiro, CodAtribuiEmpresa, CodAnteriorParceiro, CodAnteriorEmpresa, Efetuado, LinkVenda, PagoAntecipado, ValorReajustado, ReferenteNotaFiscal, PagamentoLote, PadraoRelatorio, SomenteIntegracao, AnoOcorrenciaMensal, MesOcorrenciaMensal, EmitirCheque, ChequeEmitido, ValorOriginalImovel, CodigoCondPagto )
SELECT [F Movimento Contas].EmpVinculada, [F Movimento Contas].CodigoParceiro, [F Movimento Contas].CodHistorico, [F Movimento Contas].DataMovto, [F Movimento Contas].ValorDebito, [F Movimento Contas].ValorCredito, [F Movimento Contas].Complemento, [F Movimento Contas].Plano1, [F Movimento Contas].Plano2, [F Movimento Contas].Plano3, [F Movimento Contas].ContaFinanceira, [F Movimento Contas].Confirmado, [F Movimento Contas].Integracao, [F Movimento Contas].DataPagto, [F Movimento Contas].DataVencto, [F Movimento Contas].MovPagtoLote, [F Movimento Contas].SelPagtoLote, [F Movimento Contas].Observacao, [F Movimento Contas].NumDoc, [F Movimento Contas].CodImovel, [F Movimento Contas].AgrupadorVenda, [F Movimento Contas].ClassificacaoVenda, [F Movimento Contas].SofreReajuste, [F Movimento Contas].IndiceReajuste, [F Movimento Contas].CodAtribuiParceiro, [F Movimento Contas].CodAtribuiEmpresa, [F Movimento Contas].CodAnteriorParceiro, [F Movimento Contas].CodAnteriorEmpresa, [F Movimento Contas].Efetuado, [F Movimento Contas].LinkVenda, [F Movimento Contas].PagoAntecipado, [F Movimento Contas].ValorReajustado, [F Movimento Contas].ReferenteNotaFiscal, [F Movimento Contas].PagamentoLote, [F Movimento Contas].PadraoRelatorio, [F Movimento Contas].SomenteIntegracao, [F Movimento Contas].AnoOcorrenciaMensal, [F Movimento Contas].MesOcorrenciaMensal, [F Movimento Contas].EmitirCheque, [F Movimento Contas].ChequeEmitido, [F Movimento Contas].ValorOriginalImovel, [F Movimento Contas].CodigoCondPagto
FROM (Parceiros INNER JOIN (Indices INNER JOIN (Imoveis INNER JOIN (Historico INNER JOIN ((EmpMaster INNER JOIN EmpVinculada ON EmpMaster.CodigoMaster=EmpVinculada.CodigoMaster) INNER JOIN ([F Contas Financeiras] INNER JOIN (([F Movimento Contas] INNER JOIN Plano1 ON [F Movimento Contas].Plano1=Plano1.Plano1) INNER JOIN Plano2 ON ([F Movimento Contas].Plano2=Plano2.Plano2) AND (Plano1.Plano1=Plano2.Plano1)) ON [F Contas Financeiras].CodigoConta=[F Movimento Contas].ContaFinanceira) ON EmpVinculada.CodigoVinculada=[F Movimento Contas].EmpVinculada) ON Historico.CodHistorico=[F Movimento Contas].CodHistorico) ON Imoveis.CodImovel=[F Movimento Contas].CodImovel) ON Indices.CodIndice=[F Movimento Contas].IndiceReajuste) ON Parceiros.CodigoParceiro=[F Movimento Contas].CodigoParceiro) INNER JOIN Plano3 ON (Plano2.Plano2=Plano3.Plano2) AND (Plano3.Plano3=[F Movimento Contas].Plano3)
WHERE ((([F Movimento Contas].Confirmado)=True) And (([F Movimento Contas].DataPagto)>=Formulários!ArquivoMorto!DataIniRel And ([F Movimento Contas].DataPagto)<=Formulários!ArquivoMorto!DataFimRel));
